  "agent.sweep": {
    "id": "agent.sweep",
    "area": "accounts",
    "command": "agent sweep",
    "title": "Sweep an agent's Safe",
    "sdk": "client.me.agents.sweep",
    "row": null,
    "about": "Moves all held settlement assets from an agent's Safe to you, or to a recipient you name. You approve one operation from your Safe, with one `AgentOwner.sweep(safe, to, token)` call per asset. Its key and Seats stay unchanged, and a frozen agent can be swept too.",
    "who": "The agent's owner, signed in.",
    "changes": "The owner's Safe calls `AgentOwner.sweep` for each selected asset. Once it lands, the agent's Safe holds none of those assets and the recipient holds what it held.",
    "notes": [
      "`--asset` selects one settlement asset by symbol. Omit it to sweep all held settlement assets.",
      "`--to` accepts an email, @handle or address through the recipient resolver; your own Safe when omitted.",
      "You approve all selected assets together. Each approval row shows its asset's balance at preparation.",
      "Settlement reports each event amount. In a verified successful operation, a token that became empty before execution reports zero without an event.",
      "Without `--no-wait` the command follows your approval, then the sweep until it lands.",
      "Only one change of an agent waits for your approval at a time."
    ],
    "mistakes": [],
    "returns": [
      {
        "field": "agentId",
        "meaning": "The agent."
      },
      {
        "field": "handle",
        "meaning": "Its `@handle` without the `@`."
      },
      {
        "field": "state",
        "meaning": "`landed` once the sweep is on chain."
      },
      {
        "field": "txHash",
        "meaning": "The transaction that carried it."
      },
      {
        "field": "swept",
        "meaning": "A list of assets, with each actual raw amount and its recipient."
      }
    ],
    "refusals": [
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "You do not own an agent with that handle or id."
      },
      {
        "code": "WRONG_STATE",
        "when": "Its Safe holds none of the asset, so nothing is signed; or it is not active or frozen, or another change of it waits for your approval."
      },
      {
        "code": "INVALID_INPUT",
        "when": "The asset is not a settlement asset, or the recipient locator is invalid or unresolved."
      },
      {
        "code": "NOT_AUTHENTICATED",
        "when": "No valid sign-in on this machine."
      }
    ],
    "acceptance": [
      {
        "claim": "Omitting the asset sweeps an EURC-only Safe or all held settlement assets with one approval; an explicit asset selects only that asset.",
        "was": [
          "backend accounts/agents/tests/sweep.test.ts"
        ]
      },
      {
        "claim": "Email, @handle and address recipients resolve to the recipient's Safe before approval; invalid or unresolved locators open nothing.",
        "was": [
          "backend accounts/agents/tests/sweep.test.ts"
        ]
      },
      {
        "claim": "Settlement binds the successful receipt to the approved operation and owner, checks each event's Safe, token and recipient, and reports actual amounts. Selected tokens that became empty before execution report zero only when the provider supplies the operation's logs; omitted or null logs, invalid events and duplicate events fail the change.",
        "was": [
          "backend accounts/agents/tests/sweep.test.ts"
        ]
      },
      {
        "claim": "A frozen agent stays frozen; an empty Safe, unknown asset or non-owner is refused.",
        "was": [
          "backend accounts/agents/tests/sweep.test.ts"
        ]
      },
      {
        "claim": "Aborting waitChange during its polling sleep returns CANCELLED.",
        "was": [
          "sdk platform/tests/sdk-cutover-public-contracts.test.ts"
        ]
      },
      {
        "claim": "CLI preparation and settlement show each asset separately with actual amounts after landing.",
        "was": [
          "cli commands/agent/tests/presentation.test.ts"
        ]
      }
    ],
    "events": [
      {
        "event": "agent_transitioned",
        "transition": "swept"
      }
    ],
    "designed": {
      "slice": "W9",
      "summary": "Move everything the agent's Safe holds to you, or to an address you name. Its Seats and its key are untouched. Use it before you remove an agent, or whenever you want its money back.",
      "synopsis": "capxul agent sweep <handle> [--to <email|@handle|address>] [--asset <asset>]",
      "who": "The agent's owner.",
      "signs": "You, on the approval page: your Safe calls the owner module, which pays out of the agent's Safe.",
      "method": "client.me.agents.sweep",
      "flags": [
        {
          "flag": "`--to`",
          "meaning": "Where the money goes. Defaults to your own Safe"
        },
        {
          "flag": "`--asset`",
          "meaning": "One asset only. Defaults to everything it holds"
        }
      ],
      "example": {
        "cli": "$ capxul agent sweep ledger\nAgent       Ledger · @ledger\nHolds       312.50 USDC\nTo          you · 0xd4a1…9c03\n✓ Prepared\n… Approve in your browser (opened)\n✓ Signed\n✓ Swept     312.50 USDC · 0x5b20…7e1f",
        "sdk": "const swept = await client.me.agents.sweep(\"ledger\");",
        "returns": "{\n  \"ok\": true,\n  \"value\": {\n    \"handle\": \"ledger\",\n    \"swept\": [\n      {\n        \"asset\": \"USDC\",\n        \"amount\": \"312.50\"\n      }\n    ],\n    \"to\": \"0xd4a1…9c03\"\n  }\n}"
      },
      "refusals": [
        {
          "code": "ROLE_PERMISSION_DENIED",
          "exit": 4,
          "when": "You do not own the agent",
          "contract": "`NotOwner()`"
        },
        {
          "code": "WRONG_STATE",
          "exit": 2,
          "when": "Its Safe holds nothing (not an error: nothing is signed)",
          "contract": "none"
        }
      ],
      "call": "`AgentOwner.sweep(safe, to, asset)`, one `Payments.send` from the agent's Safe made by the owner module."
    },
    "source": "apps/docs/factory/operations/agent.sweep.yaml"
  },
