  "agreement.collect": {
    "id": "agreement.collect",
    "area": "payroll",
    "command": "agreement collect",
    "title": "Collect your pay",
    "sdk": "client.agreements.collect",
    "row": null,
    "about": "Collects everything released on an agreement as one payment from the payer. With nothing released yet, nothing is signed and it tells you when the next release lands. With `--org`, the payee Organization's Safe collects instead, as a Director proposal.",
    "who": "The payee, from their personal Safe. With `--org`, a Director of the payee Organization.",
    "changes": "You sign one call from your personal Safe, and the payer's Safe pays you the released amount as one payment. On v4 the call is `Agreements.collect`, and Budgets pays it through the payer's payout role. With `--org`, it opens a proposal at the Organization Safe's next nonce and changes nothing until enough Directors approve.",
    "notes": [
      "Before you approve, it shows the amount, the period it covers and, unless the payer turned previews off, a payslip preview.",
      "It follows the collection until its payment settles, unless you pass `--no-wait`.",
      "It works on active, paused, ending and ended agreements."
    ],
    "mistakes": [
      {
        "what": "The payer's Safe holds less than the collection",
        "fix": "It is refused with `PAYER_BALANCE_TOO_LOW` before anything is signed. Your pay stays owed. Try again once the payer adds funds."
      },
      {
        "what": "The payer's payout ceiling cannot cover it, such as during a freeze",
        "fix": "It is refused with `ROLE_PERMISSION_DENIED` and names what the ceiling has left. Your pay stays owed."
      },
      {
        "what": "The offer has not been accepted yet",
        "fix": "It is refused with `WRONG_STATE`. Accept it first with `agreement accept`."
      }
    ],
    "returns": [
      {
        "field": "status",
        "meaning": "`settled` or `submitted`; `nothing_released` with nothing signed; or `awaiting_approval` with `--no-wait`."
      },
      {
        "field": "collected",
        "meaning": "The amount collected, or `0.00`."
      },
      {
        "field": "payment",
        "meaning": "The one payment the payer made."
      },
      {
        "field": "agreement",
        "meaning": "The agreement after the collection."
      },
      {
        "field": "nextReleaseAt",
        "meaning": "With nothing released, when the next release lands."
      }
    ],
    "refusals": [
      {
        "code": "PAYER_BALANCE_TOO_LOW",
        "when": "The payer's Safe holds less than the collection. Nothing is signed and the pay stays owed."
      },
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "The payer's payout ceiling cannot cover it, such as during a freeze, or you are not the payee."
      },
      {
        "code": "WRONG_STATE",
        "when": "The offer was not accepted or was withdrawn, or an earlier collection is still on its way."
      }
    ],
    "acceptance": [
      {
        "claim": "A collection that lands pays the released pay as one Payment and reports `collected` once.",
        "was": [
          "backend collect.test.ts"
        ]
      },
      {
        "claim": "The next collection claims from where the last ended.",
        "was": [
          "backend collect.test.ts"
        ]
      },
      {
        "claim": "Nothing released signs nothing, stores nothing and says when the next release lands.",
        "was": [
          "backend collect.test.ts"
        ]
      },
      {
        "claim": "A short payer Safe is `PAYER_BALANCE_TOO_LOW`, the pay stays owed, and it works once funds are added.",
        "was": [
          "backend collect.test.ts"
        ]
      },
      {
        "claim": "A ceiling a freeze left empty is `ROLE_PERMISSION_DENIED`, and it works after the freeze.",
        "was": [
          "backend collect.test.ts"
        ]
      },
      {
        "claim": "A collection still on its way blocks the next one.",
        "was": [
          "backend collect.test.ts"
        ]
      },
      {
        "claim": "On v4 the call is Agreements.collect, refused first when the payer's Safe or its payout ceiling on Budgets' Roles is short.",
        "was": [
          "backend agreements-v4.test.ts"
        ]
      }
    ],
    "events": [],
    "designed": {
      "slice": "W2",
      "summary": "Collect everything released so far. Paid from the budget's reservation, even if the budget has since closed.",
      "synopsis": "capxul agreement collect <id>",
      "who": "The payee.",
      "signs": "You: your own Safe signs, sponsored by Capxul's paymaster",
      "method": "client.me.agreements.collect",
      "flags": [],
      "example": {
        "cli": "$ capxul agreement collect ag_01K1…\nReleased    15,000.00 USDC (February 2027)\n✓ Collected 0x3a90…11cd · payment kind 4",
        "sdk": "await client.me.agreements.collect(\"ag_01K1…\");",
        "returns": "{\n  \"ok\": true,\n  \"value\": {\n    \"status\": \"settled\",\n    \"collected\": \"15000.00\"\n  }\n}"
      },
      "refusals": [
        {
          "code": "WRONG_STATE",
          "exit": 2,
          "when": "Nothing released yet (not an error: prints the next release)",
          "contract": "none"
        }
      ],
      "call": "`Agreements.collect(id, amount)`, which calls `Budgets.payReserved` (kind 4).",
      "concepts": [
        "c-agreements",
        "c-payments"
      ]
    },
    "source": "apps/docs/factory/operations/agreement.collect.yaml"
  },
