  "auth.login": {
    "id": "auth.login",
    "area": "accounts",
    "command": "auth login",
    "title": "Sign in",
    "sdk": "client.auth.signIn",
    "row": null,
    "about": "Signs you in with your email and a six-digit code sent to it. At a terminal it sends the code, asks for it and finishes in one go. In a script, an agent or a `--json` run without `--otp-stdin`, it only sends the code and tells you to finish with `capxul auth verify <code>`. With `--own-key` it sets up an AI's own account, which signs with its own key.",
    "who": "Anyone with an email address. No earlier sign-in is needed.",
    "changes": "Saves a session for this person on this machine and makes them the current person. With `--own-key` it also keeps the AI's key and sets up its account and Safe.",
    "notes": [
      "It never opens a browser. If your account is not ready yet, the result says `setup-required` and gives the web link where you finish setup, then `capxul account retry` to check it.",
      "At a terminal you get three tries at the code. With `--otp-stdin` you get one.",
      "`--own-key` needs the code piped into `--otp-stdin` when no terminal is attached. A new AI account also needs `--name`, `--country` and `--handle`.",
      "Signing in again with `--own-key` keeps the key the account already signs with."
    ],
    "mistakes": [
      {
        "what": "Passed `--name`, `--country` or `--handle` without `--own-key`",
        "fix": "Refused with `CLI_USAGE`, because those flags only set up an AI's account. Add `--own-key`, or drop them for a normal sign-in."
      },
      {
        "what": "Typed a wrong code",
        "fix": "The backend refuses it as `INVALID_INPUT`. At a terminal you are asked again, up to three times. After that, run `capxul auth login` again."
      },
      {
        "what": "Ran it in a script without `--email`",
        "fix": "Refused with `CLI_USAGE` because there is no terminal to ask for it. Pass `--email`."
      }
    ],
    "returns": [
      {
        "field": "authenticated",
        "meaning": "`true` once the code is verified; `false` with `status: otp-required` when the command only sent the code."
      },
      {
        "field": "email",
        "meaning": "The person signing in."
      },
      {
        "field": "authUserId",
        "meaning": "The signed-in person's ID."
      },
      {
        "field": "expiresAt",
        "meaning": "When the saved session expires."
      },
      {
        "field": "setupState",
        "meaning": "`ready`, or `setup-required` with `setupUrl` and the `next.argv` to check again."
      },
      {
        "field": "journeyId",
        "meaning": "Only while it waits for the code, to finish with `capxul auth verify`."
      }
    ],
    "refusals": [
      {
        "code": "CLI_USAGE",
        "when": "`--name`, `--country` or `--handle` without `--own-key`, or no `--email` when there is no terminal to ask for it."
      },
      {
        "code": "INVALID_INPUT",
        "when": "The backend refuses the code. At a terminal it asks again, up to three times."
      }
    ],
    "acceptance": [
      {
        "claim": "Without a terminal and without `--otp-stdin`, it sends the code and returns `authenticated` false with `status` `otp-required` and the `capxul auth verify` argv, and saves no session.",
        "was": [
          "cli auth.test.ts"
        ]
      },
      {
        "claim": "With `--otp-stdin` and a correct code it saves the session and makes the person current, so `capxul auth list` marks them current.",
        "was": [
          "cli auth.test.ts"
        ]
      }
    ],
    "events": [
      "auth_failed",
      "auth_otp_delivered",
      "auth_otp_requested"
    ],
    "designed": {
      "slice": "W9",
      "summary": "An agent signs in with its key alone. With `--own-key` and no `--email`, the CLI signs a challenge from Capxul with the key and is signed in as that agent, with no code and no inbox. A person still signs in by email. `capxul agent create` makes the account the key signs for.",
      "synopsis": "capxul auth login --own-key file|env",
      "who": "An agent whose account exists, on the machine that holds its key.",
      "signs": "The agent's own key signs the challenge. Nothing moves.",
      "method": "client.auth.signInWithKey",
      "flags": [
        {
          "flag": "`--own-key`",
          "meaning": "Where the key is: a private file (`file`) or `CAPXUL_PRIVATE_KEY` (`env`)"
        }
      ],
      "example": {
        "cli": "$ capxul auth login --own-key env\nSigned in as Ledger (@ledger), an agent owned by dana@acme.test.\nsigns      its own key · env",
        "sdk": "const client = createCapxulClient({\n  publishableKey,\n  signer: localPrivateKeySigner({ privateKey: process.env.CAPXUL_PRIVATE_KEY }),\n});",
        "returns": "{\n  \"ok\": true,\n  \"value\": {\n    \"handle\": \"ledger\",\n    \"kind\": \"agent\",\n    \"owner\": \"dana@acme.test\"\n  }\n}"
      },
      "refusals": [
        {
          "code": "NOT_AUTHENTICATED",
          "exit": 3,
          "when": "The key signs for no agent account, or the agent is frozen",
          "contract": "none"
        }
      ],
      "call": "None: the backend checks the signed challenge against the agent's Safe signer."
    },
    "source": "apps/docs/factory/operations/auth.login.yaml"
  },
