  "bank.pay": {
    "id": "bank.pay",
    "area": "banking",
    "command": "bank pay",
    "title": "Pay a bank account",
    "sdk": "client.approvals.prepare",
    "row": "payments.commands.prepare",
    "about": "Pays a bank account: your own (`self`), a saved contact's, or a new one. An amount on its own fixes what reaches the bank. Add `USDC` or `EURC` after the amount to fix what leaves your Safe instead. You approve the payment in your browser.",
    "who": "A verified, signed-in person. For an Organization, a member with a spending allowance in the funding asset.",
    "changes": "After you approve it in the browser, it sends the funding asset from your Safe, or from the Organization's spending allowance, and the payout goes to the bank.",
    "notes": [
      "Bank delivery can take days. If the payout is in transit when the approval deadline passes, the command ends normally and names `capxul payment wait`.",
      "Reuse `--request-key` to retry the same payout without paying twice.",
      "With `--json` it returns as soon as the approval waits for you, with the stage `quoted`.",
      "Scripts can pass `--input FILE` with the payout as JSON, including a new contact and their bank details, so the numbers never enter a command line.",
      "On Protocol v4 a personal payout leaves your Safe in one `Payments.send` (kind 0) to the bank partner's deposit address for the quote, after `approve` of that amount. The Safe is the one Companies House derives for your email."
    ],
    "mistakes": [
      {
        "what": "You pay a GBP account with EURC",
        "fix": "It refuses with `INVALID_INPUT`. Use USDC."
      },
      {
        "what": "The quote expires, or the bank account changes, before you approve",
        "fix": "It refuses with `WRONG_STATE` and nothing is sent. Run `bank pay` again for a new quote."
      },
      {
        "what": "You are not verified",
        "fix": "It refuses with `VERIFICATION_REQUIRED` and names `capxul verify start`."
      }
    ],
    "returns": [
      {
        "field": "status",
        "meaning": "`awaiting_approval` with `approvalId` and `approvalUrl` in `--json`, or `in_transit` when the deadline passes while the bank delivers."
      },
      {
        "field": "stage",
        "meaning": "`quoted`, `funding`, `in_transit`, `delivered` or `needs_attention`, with `stageReason`."
      },
      {
        "field": "quote",
        "meaning": "What reaches the bank (`receive`), what leaves the Safe (`send`), the rate, slippage and when it expires."
      },
      {
        "field": "paymentIds",
        "meaning": "The Payments it made."
      },
      {
        "field": "warnings",
        "meaning": "Anything the payer should know, each with its code."
      }
    ],
    "refusals": [
      {
        "code": "INVALID_INPUT",
        "when": "The amount unit and `--asset` disagree, or the asset cannot pay that currency, such as EURC to GBP."
      },
      {
        "code": "WRONG_STATE",
        "when": "The quote expired or the bank account changed before approval. Nothing is sent."
      },
      {
        "code": "VERIFICATION_REQUIRED",
        "when": "You are not verified. It names `capxul verify start`."
      },
      {
        "code": "INSUFFICIENT_BALANCE",
        "when": "The Safe or the allowance cannot fund the payout."
      },
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "For an Organization, you hold no spending allowance in the funding asset."
      }
    ],
    "acceptance": [
      {
        "claim": "An expired quote, or a changed bank account, names `bank pay` again for a new quote.",
        "was": [
          "cli payout.test.ts"
        ]
      },
      {
        "claim": "The view shows the locked bank amount and the slippage buffer inside the funding.",
        "was": [
          "cli payout-view.test.ts"
        ]
      },
      {
        "claim": "A failed payout names why it failed and where its refund went.",
        "was": [
          "cli payout.test.ts"
        ]
      },
      {
        "claim": "A replay of a known `--request-key` is never refused and pays nothing twice.",
        "was": [
          "backend prepare.test.ts"
        ]
      },
      {
        "claim": "An Organization send above its allowance cap is refused before anything is written.",
        "was": [
          "backend prepare.test.ts"
        ]
      }
    ],
    "events": [],
    "designed": {
      "slice": "W2",
      "summary": "Same command on v4. The funding asset leaves your Safe in one `Payments.send` to the bank partner's deposit address for the quote. For an Organization it is a spend from a budget you hold the hat of, named with `--from`.",
      "synopsis": "capxul bank pay <self|contact> <amount> [USDC|EURC] [--account <id>] [--org <org> --from <budget>] [--request-key <key>]",
      "who": "A verified, signed-in person. For an Organization, the wearer of the budget's hat or above.",
      "signs": "Personal: your own Safe, sponsored by Capxul's paymaster. Organization: your own Safe calls Budgets, and the company Safe pays through its Roles payout role.",
      "method": "client.approvals.prepare",
      "flags": [
        {
          "flag": "`--from`",
          "meaning": "The budget an Organization pays from (a spending allowance is a budget in v4)"
        }
      ],
      "example": {
        "cli": "$ capxul bank pay self 500 --org acme --from office-costs\nQuote       500.00 GBP to Barclays ••42 · 634.10 USDC from Office costs\nSigns       you · Office costs\n✓ Sent      0x2f91…aa07 · in transit to the bank",
        "sdk": "await client.approvals.prepare({ kind: \"bank_payout\", to: \"self\", amount: \"500\", org: \"acme\", from: \"office-costs\" });",
        "returns": "{\n  \"ok\": true,\n  \"value\": {\n    \"payout\": {\n      \"stage\": \"in_transit\"\n    },\n    \"payment\": {\n      \"paymentId\": \"0x2f91…aa07\"\n    }\n  }\n}"
      },
      "refusals": [
        {
          "code": "PAYROLL_BUDGET_EXCEEDED",
          "exit": 2,
          "when": "The budget has less left this period than the funding amount",
          "contract": "`OverBudget(id, left, requested)`; Roles `AllowanceExceeded`"
        },
        {
          "code": "WRONG_STATE",
          "exit": 2,
          "when": "The quote expired, or the budget or one above it is closed",
          "contract": "`BudgetIsClosed(id)`"
        },
        {
          "code": "VERIFICATION_REQUIRED",
          "exit": 2,
          "when": "You are not verified for the currency",
          "contract": "none"
        },
        {
          "code": "ROLE_PERMISSION_DENIED",
          "exit": 4,
          "when": "You wear no hat on that budget or above it",
          "contract": "`NotAuthorised(id, who)`"
        }
      ],
      "call": "Personal: `token.approve(Payments, amount)` and `Payments.send(item)` (kind 0) to the quote's deposit address. Organization: `Budgets.spend(id, depositAddress, amount, 0, documentHash, jobNonce)`.",
      "concepts": [
        "c-payments",
        "c-budgets"
      ]
    },
    "source": "apps/docs/factory/operations/bank.pay.yaml"
  },
