  "inbox.pay": {
    "id": "inbox.pay",
    "area": "payments",
    "command": "inbox pay",
    "title": "Pay a request",
    "sdk": "client.approvals.prepare",
    "row": "payments.commands.prepareRequest",
    "about": "Pays a request sent to you or to the Organization you act as, for exactly the amount and asset the request fixed. The CLI prepares the payment and gives you an approval link. You approve it in your browser, and the CLI follows it until it settles.",
    "who": "The payer: a signed-in person for their own inbox, or a member of the Organization paying under a spending allowance they hold.",
    "changes": "Prepares a payment and opens an approval. Nothing moves until you approve it in the browser, where your own key signs it. An AI with its own key signs at once.",
    "notes": [
      "An Organization payment needs `--permission-id`. Find yours with `capxul org me`.",
      "With `--json` it returns `awaiting_approval` with the approval link and the `capxul payment wait` command to follow it.",
      "Without `--timeout-seconds` it follows until the approval lapses. You can set 1 to 3600. Stopping early sends nothing.",
      "`--resume` opens the approval again for a request whose payment is already prepared.",
      "On Protocol v4 a spending allowance pays the request through Budgets, now or with `--on`. The request then records the payment id Budgets derives, so its checkout, Database and activity match that payment. More than the allowance has left is refused before you sign. With `--on` the budget reserves the amount when you sign, and the company Safe needs the money only on that date (CAP-1252)."
    ],
    "mistakes": [
      {
        "what": "Tried to pay a request that is not open",
        "fix": "Refused with `WRONG_STATE`. The message gives the command that reads its current state."
      },
      {
        "what": "Paid from an Organization without `--permission-id`",
        "fix": "Refused with `CLI_USAGE`. Run `capxul org me` to find the spending allowance to pay under."
      },
      {
        "what": "Let the approval expire, or rejected it on the approval page",
        "fix": "Expiry ends with `WRONG_STATE` and a rejection with `CANCELLED`. Nothing was sent in either case."
      }
    ],
    "returns": [
      {
        "field": "status",
        "meaning": "With `--json`, `awaiting_approval` while the approval waits for you."
      },
      {
        "field": "approvalId",
        "meaning": "The approval's ID, which `capxul payment wait` follows."
      },
      {
        "field": "approvalUrl",
        "meaning": "The approval page where you sign."
      },
      {
        "field": "paymentIds",
        "meaning": "The payments the approval covers."
      },
      {
        "field": "expiresAt",
        "meaning": "When the approval lapses."
      },
      {
        "field": "next",
        "meaning": "The `capxul payment wait` command that follows it."
      },
      {
        "field": "approval",
        "meaning": "When followed to the end, the approval as it ended."
      },
      {
        "field": "payments",
        "meaning": "When followed to the end, each payment it moved, as it stands."
      }
    ],
    "refusals": [
      {
        "code": "CLI_USAGE",
        "when": "An Organization payment without `--permission-id`, both `--on` and `--at`, or the Invoice is unavailable to this payer."
      },
      {
        "code": "WRONG_STATE",
        "when": "The request is not open. The message names the command that reads it."
      },
      {
        "code": "INVALID_INPUT",
        "when": "The confirmation, prepared value or purpose changed, or the date is under an hour ahead."
      },
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "You are not the addressed payer, or the signer is refused."
      },
      {
        "code": "INSUFFICIENT_BALANCE",
        "when": "The paying Safe holds less than the request."
      },
      {
        "code": "NOT_AUTHENTICATED",
        "when": "You are not signed in."
      }
    ],
    "acceptance": [
      {
        "claim": "It pays exactly the amount and asset the request fixed, and a prepared payment that does not match the Invoice is refused.",
        "was": [
          "backend prepare-request.test.ts"
        ]
      },
      {
        "claim": "A fresh request key cannot bypass a live Invoice attempt, and dropping lineage cannot bypass an issued Invoice.",
        "was": [
          "backend prepare-request.test.ts"
        ]
      },
      {
        "claim": "A principal who is not the addressed payer is refused.",
        "was": [
          "backend prepare-request.test.ts"
        ]
      },
      {
        "claim": "A date under an hour ahead is refused before any Payment is born.",
        "was": [
          "backend prepare-request.test.ts"
        ]
      },
      {
        "claim": "A request that is no longer open names the read for it.",
        "was": [
          "cli pay.test.ts"
        ]
      }
    ],
    "events": [],
    "designed": {
      "slice": "W2",
      "summary": "Same command on v4. A personal payer pays the request with one `Payments.send` stamped as an invoice. An Organization pays it from a budget it holds the hat of, so `--from <budget>` replaces `--permission-id`. Spending allowances are budgets in v4.",
      "synopsis": "capxul inbox pay <request> [--org <org> --from <budget>] [--on <day> | --at <time>] [--resume] [--timeout-seconds <n>]",
      "who": "The payer. For an Organization, the wearer of the budget's hat or of a budget above it.",
      "signs": "Personal: your own Safe, sponsored by Capxul's paymaster. Organization: your own Safe calls Budgets, and the company Safe pays through its Roles payout role.",
      "method": "client.account.inbox.pay",
      "flags": [
        {
          "flag": "`--from`",
          "meaning": "The budget an Organization pays from (replaces `--permission-id`)"
        },
        {
          "flag": "`--on`, `--at`",
          "meaning": "Pay later. Personal: a signed operation sent on the day. Organization: a dated payment the budget reserves now"
        }
      ],
      "example": {
        "cli": "$ capxul inbox pay req_01K3… --org acme --from operations\nRequest     1,200.00 USDC to Parts Ltd · invoice INV-0042\nBudget      Operations · 47,200 left this year\nSigns       you · Ops lead\n✓ Paid      0x0b7e…44d2 · Operations has 46,000 left",
        "sdk": "await client.account.inbox.pay(\"req_01K3…\", { org: \"acme\", from: \"operations\" });",
        "returns": "{\n  \"ok\": true,\n  \"value\": {\n    \"request\": {\n      \"status\": \"paid\"\n    },\n    \"payment\": {\n      \"paymentId\": \"0x0b7e…44d2\",\n      \"kind\": \"invoice\"\n    }\n  }\n}"
      },
      "refusals": [
        {
          "code": "WRONG_STATE",
          "exit": 2,
          "when": "The request is not open, or the budget or one above it is closed",
          "contract": "`BudgetIsClosed(id)`"
        },
        {
          "code": "PAYROLL_BUDGET_EXCEEDED",
          "exit": 2,
          "when": "The budget has less left this period than the request",
          "contract": "`OverBudget(id, left, requested)`; Roles `AllowanceExceeded`"
        },
        {
          "code": "INSUFFICIENT_BALANCE",
          "exit": 2,
          "when": "The paying Safe holds less than the request",
          "contract": "the token's own transfer revert, bubbled up by Payments"
        },
        {
          "code": "ROLE_PERMISSION_DENIED",
          "exit": 4,
          "when": "You wear no hat on that budget or above it",
          "contract": "`NotAuthorised(id, who)`"
        }
      ],
      "call": "Personal: `token.approve(Payments, amount)` and `Payments.send(item)` with kind 1 (invoice) and the request's document hash. Organization: `Budgets.spend(id, issuerSafe, amount, 1, documentHash, jobNonce)`, or `Budgets.schedule(...)` when dated.",
      "concepts": [
        "c-payments",
        "c-budgets"
      ]
    },
    "source": "apps/docs/factory/operations/inbox.pay.yaml"
  },
