  "invite.accept": {
    "id": "invite.accept",
    "area": "governance",
    "command": "invite accept",
    "title": "Accept an invitation",
    "sdk": "client.org(orgId).invitations.accept",
    "row": null,
    "about": "Accepts one invitation sent to you, at the exact offer digest you reviewed. The grants it offers are then set up for you. For a business invitation (an ID starting `inv_kyb_`), it starts your verification instead.",
    "who": "The person the invitation was sent to.",
    "changes": "It records your consent to that exact offer, and Capxul then grants what it offered. You sign nothing.",
    "notes": [
      "A script must pass `--offer-digest` and `--confirm`. At a terminal you can leave the digest out, and the command uses the one it shows you.",
      "Accepting again with the same digest returns the same result and writes nothing.",
      "An invitation with no grants makes you an active member at once.",
      "`--input` is only for `inv_kyb_` business invitations."
    ],
    "mistakes": [
      {
        "what": "The offer changed since you read its digest",
        "fix": "It refuses with `WRONG_STATE`. Read it again with `capxul invite list` and accept the new digest."
      },
      {
        "what": "The offer expired, or is no longer pending",
        "fix": "It refuses with `WRONG_STATE`. Ask the Organization to send a new invitation."
      },
      {
        "what": "You are signed in as someone other than the recipient",
        "fix": "It refuses with `ROLE_PERMISSION_DENIED`. Sign in as the person it was sent to."
      }
    ],
    "returns": [
      {
        "field": "id",
        "meaning": "The invitation."
      },
      {
        "field": "orgId",
        "meaning": "The Organization you are joining."
      },
      {
        "field": "phase",
        "meaning": "`active` at once for a Seat-only offer; `pending_grant` while an offer with grants is set up, then `active`."
      },
      {
        "field": "acceptedAt",
        "meaning": "When your consent was recorded."
      },
      {
        "field": "grants",
        "meaning": "The allowances and Manage allowances being set up for you."
      },
      {
        "field": "recovery",
        "meaning": "`grant_pending` while the grant lands, or `null` once nothing is pending."
      },
      {
        "field": "recoveryActions",
        "meaning": "Whether a retry of the grant's verification is available."
      },
      {
        "field": "offerDigest",
        "meaning": "The digest you consented to."
      }
    ],
    "refusals": [
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "You are not the person it was sent to, or no such invitation exists in that Organization. Nothing was written."
      },
      {
        "code": "WRONG_STATE",
        "when": "The offer changed since you read its digest, it is not pending yet, it has expired, or you already accepted it at a different digest."
      },
      {
        "code": "NOT_AUTHENTICATED",
        "when": "No valid sign-in on this machine."
      }
    ],
    "acceptance": [
      {
        "claim": "Consent, its grant command and the durable drive call commit in one transaction.",
        "was": [
          "backend accept.test.ts"
        ]
      },
      {
        "claim": "The stored digest replays without writing, and a different one is refused.",
        "was": [
          "backend accept.test.ts"
        ]
      },
      {
        "claim": "A malformed acceptance digest is refused `INVALID_INPUT` before consent.",
        "was": [
          "backend accept.test.ts"
        ]
      },
      {
        "claim": "It needs the exact grantee and the live digest, and is refused after an ending request or at expiry.",
        "was": [
          "backend accept.test.ts"
        ]
      }
    ],
    "events": [],
    "designed": null,
    "source": "apps/docs/factory/operations/invite.accept.yaml"
  },
