  "org.books.accounts.reclassify": {
    "id": "org.books.accounts.reclassify",
    "area": "books",
    "command": "org books accounts reclassify",
    "title": "Reclassify rows",
    "sdk": "client.org(orgId).books.accounts.reclassify",
    "row": null,
    "about": "Moves the rows waiting in a \"not decided\" account (4999 or 6999) to one account in a single change. It moves every row waiting there, or with `--from` and `--to` only the rows whose money falls in that period. With `--row` it moves only the rows you name.",
    "who": "Needs Manage books. An AI Seat with Manage books can run it.",
    "changes": "Each moved row takes the new account and loses any suggestion. One `rows_reclassified` fact records every row moved, so the whole change can be taken back as one. The reports read the new account at once.",
    "notes": [
      "Give only the row's ID to `--row`. The CLI finds its kind from the queue.",
      "A row you name that is not waiting in `--from-account`, or whose money falls outside the period, stays where it is. A row whose money falls both inside and outside the period, such as a stream claimed in two months, always stays, because a row has one account for all its money. The reply lists each with the reason.",
      "When nothing moves, no fact is recorded."
    ],
    "mistakes": [
      {
        "what": "You give an account that is not 4999 or 6999 as `--from-account`",
        "fix": "It refuses with `INVALID_INPUT`. Rows only move out of a \"not decided\" account."
      },
      {
        "what": "You give the same account for `--from-account` and `--to-account`",
        "fix": "It refuses with `INVALID_INPUT`."
      },
      {
        "what": "`--to` is before `--from`",
        "fix": "The CLI refuses with `CLI_USAGE`."
      },
      {
        "what": "You run it without Manage books",
        "fix": "It refuses with `ROLE_PERMISSION_DENIED` (`manage_books_required`)."
      }
    ],
    "returns": [
      {
        "field": "fromAccount",
        "meaning": "The not-decided account the rows left."
      },
      {
        "field": "toAccount",
        "meaning": "The account they moved to."
      },
      {
        "field": "factId",
        "meaning": "The one `rows_reclassified` fact, or `null` when nothing moved."
      },
      {
        "field": "moved",
        "meaning": "The rows moved."
      },
      {
        "field": "refused",
        "meaning": "The rows that stayed, each with the reason."
      }
    ],
    "refusals": [
      {
        "code": "CLI_USAGE",
        "when": "`--to` is before `--from`."
      },
      {
        "code": "INVALID_INPUT",
        "when": "The from-account is not 4999 or 6999, or the two accounts are the same."
      },
      {
        "code": "WRONG_STATE",
        "when": "There is no chart."
      },
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "You lack Manage books (`manage_books_required`)."
      }
    ],
    "acceptance": [
      {
        "claim": "It moves every row waiting in 6999 in the period to one account, as one fact.",
        "was": [
          "backend reclassify.test.ts"
        ]
      },
      {
        "claim": "Named rows move, and the ones that cannot stay with the reason.",
        "was": [
          "backend reclassify.test.ts"
        ]
      },
      {
        "claim": "A commitment whose claims fall both sides of the period stays, and is always listed.",
        "was": [
          "backend reclassify.test.ts"
        ]
      },
      {
        "claim": "When nothing moves it records no fact and posts nothing.",
        "was": [
          "backend reclassify.test.ts"
        ]
      },
      {
        "claim": "A second call after every row moved moves nothing.",
        "was": [
          "backend reclassify.test.ts"
        ]
      }
    ],
    "events": [],
    "designed": null,
    "source": "apps/docs/factory/operations/org.books.accounts.reclassify.yaml"
  },
