  "org.books.accounts.review": {
    "id": "org.books.accounts.review",
    "area": "books",
    "command": "org books accounts review",
    "title": "Review the queue",
    "sdk": "client.org(orgId).books.accounts.review",
    "row": null,
    "about": "Lists the rows still waiting in a \"not decided\" account (4999 or 6999), oldest first, with the account name someone suggested for each. With `--accept <id>` it makes that suggestion a new account and moves the row to it.",
    "who": "Any member can read the queue. Accepting needs Manage books.",
    "changes": "Without `--accept`, nothing: it only reads. With it, it creates the account with an `account_created` fact, moves the row to it and records a `recategorized` fact, so the first choice stays in history.",
    "notes": [
      "Give only the row's ID to `--accept`. The CLI finds its kind from the queue.",
      "Without `--accept`, the command calls `client.org(orgId).books.accounts.review` and reads only. With it, the CLI reads the queue first, then calls `client.org(orgId).books.accounts.accept`.",
      "The new account goes under `--under` when you give it, otherwise at the top of the waiting account's type. `--name` replaces the suggested name.",
      "The queue also lists money that no one gave an account, such as a deposit from outside Capxul. Such a row has no suggestion, so accept it with `--name`."
    ],
    "mistakes": [
      {
        "what": "You give `--under` or `--name` without `--accept`",
        "fix": "The CLI refuses with `CLI_USAGE`. They only go with `--accept <id>`."
      },
      {
        "what": "You accept an ID that is not in the queue",
        "fix": "The CLI refuses with `CLI_USAGE`. Run `capxul org books accounts review` to see the rows that are waiting. The SDK call refuses a row that is not waiting with `WRONG_STATE` (`not_in_review`)."
      },
      {
        "what": "You accept a row with no suggestion and no `--name`",
        "fix": "It refuses with `INVALID_INPUT`. Give the new account's name with `--name`."
      },
      {
        "what": "You accept without Manage books",
        "fix": "It refuses with `ROLE_PERMISSION_DENIED` (`manage_books_required`). You can still read the queue. The Directors grant Manage books with `capxul org member grant`."
      }
    ],
    "returns": [
      {
        "field": "rows",
        "meaning": "Each row waiting in 4999 or 6999, oldest first, with its account and suggested name."
      }
    ],
    "refusals": [
      {
        "code": "CLI_USAGE",
        "when": "`--under` or `--name` without `--accept`, or an `--accept` ID that is not in the queue."
      },
      {
        "code": "INVALID_INPUT",
        "when": "Accepting a row with no suggestion and no `--name`."
      },
      {
        "code": "WRONG_STATE",
        "when": "The row is not waiting in review (`not_in_review`), or there is no chart."
      },
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "Accepting without Manage books. Reading the queue still works."
      }
    ],
    "acceptance": [
      {
        "claim": "It lists the rows waiting in a not-decided account with their suggestion.",
        "was": [
          "backend review.test.ts"
        ]
      },
      {
        "claim": "Money no one gave an account, such as an outside deposit, waits in the queue until someone does.",
        "was": [
          "backend review.test.ts"
        ]
      }
    ],
    "events": [],
    "designed": null,
    "source": "apps/docs/factory/operations/org.books.accounts.review.yaml"
  },
