        "json": "{\n  \"version\": 1,\n  \"command\": \"org cap-table\",\n  \"environment\": {\n    \"name\": \"devnet\",\n    \"chainId\": 84532\n  },\n  \"outcome\": \"succeeded\",\n  \"data\": {\n    \"at\": \"2027-01-04T12:00:00Z\",\n    \"total\": 9000000,\n    \"options\": 0,\n    \"pool\": 1000000,\n    \"rows\": [\n      {\n        \"shareholder\": \"Aaron (founder)\",\n        \"classes\": {\n          \"Common\": 5000000\n        },\n        \"asConverted\": 5000000,\n        \"fullyDiluted\": 0.5556\n      },\n      {\n        \"shareholder\": \"Second founder\",\n        \"classes\": {\n          \"Common\": 3000000\n        },\n        \"asConverted\": 3000000,\n        \"fullyDiluted\": 0.3333\n      }\n    ]\n  }\n}",
        "sdk": "const table = await org.equity.capTable({ fullyDiluted: true });",
