  "org.department.pay": {
    "id": "org.department.pay",
    "area": "departments",
    "command": "org department pay",
    "title": "Pay from a department",
    "sdk": "client.org(orgId).departments.pay",
    "row": null,
    "about": "Pays from a department's budget, as one of its holders: your own Safe calls Budgets for the department's budget and the company Safe pays, so no Director signs. You approve it with your own key, as any payment.",
    "who": "A holder of the department.",
    "changes": "One payment from the company Safe, counted against the department's budget this period.",
    "notes": [
      "On Protocol v4 a holder's own Safe calls `Budgets.spend` for the department's top budget, and Budgets pays from the company Safe through its Roles payout role, so no Director signs. The payment rides the same budget route as a v4 spending allowance (CAP-1211), naming the department by its `dep_…` id. A department read keeps the top budget's id, so the CLI and SDK read the department first. Only `--to` and `--amount` are built; `--document` and `--kind` are not yet."
    ],
    "mistakes": [],
    "returns": [
      {
        "field": "approvalId",
        "meaning": "The approval you sign on the approval page."
      },
      {
        "field": "paymentIds",
        "meaning": "The one payment it makes."
      }
    ],
    "refusals": [
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "More than the budget has left this period (`budget_exhausted`), or you do not hold the department (`not_holder`)."
      },
      {
        "code": "WRONG_STATE",
        "when": "The department is not active on v4, or its budget id is not known yet."
      },
      {
        "code": "INVALID_INPUT",
        "when": "The department is unknown, or the amount is not in its budget's token."
      }
    ],
    "acceptance": [
      {
        "claim": "A holder's payment from a v4 department is one `Budgets.spend` of its top budget from their own Safe, under the job nonce Budgets derives, and sending re-proves the holder.",
        "was": [
          "backend pay.test.ts"
        ]
      },
      {
        "claim": "Someone who does not hold the department is refused `ROLE_PERMISSION_DENIED` `not_holder`, and nothing is written.",
        "was": [
          "backend pay.test.ts"
        ]
      },
      {
        "claim": "A department whose top budget id is not known yet is refused `WRONG_STATE`.",
        "was": [
          "backend pay.test.ts"
        ]
      },
      {
        "claim": "More than the budget has left is refused `budget_exhausted` before anything is written or sponsored.",
        "was": [
          "backend pay.test.ts"
        ]
      },
      {
        "claim": "Before anyone signs, the route must name the department's own active top budget; another budget, an unknown one or a proposed department is closed unsent.",
        "was": [
          "sdk department-budget-route.test.ts"
        ]
      }
    ],
    "events": [
      {
        "event": "payment_transitioned",
        "transition": "settled"
      }
    ],
    "designed": {
      "slice": "W2",
      "summary": "New in v4. Pay a bill or a one-off amount straight from a budget, within what it has left this period.",
      "synopsis": "capxul org department pay <dept> --to <payee> --amount <n> --document <file|hash> [--kind bill|one-off|reimbursement|transfer]",
      "who": "The budget's office holder, or anyone above.",
      "signs": "The office holder's own Safe calls Budgets; the company Safe pays through its Roles payout role.",
      "method": "org.departments.pay",
      "flags": [
        {
          "flag": "`--to`",
          "meaning": "The payee: email, @handle or address"
        },
        {
          "flag": "`--amount`",
          "meaning": "In the budget's token"
        },
        {
          "flag": "`--document`",
          "meaning": "The invoice or receipt; its hash is stamped on the payment"
        },
        {
          "flag": "`--kind`",
          "meaning": "Payment kind 0 to 3 (default bill)"
        }
      ],
      "example": {
        "cli": "$ capxul org department pay platform --to vendor@cloud.test --amount 12000 --document ./invoice-0042.pdf\nBudget      Platform team · 120,000 left this year\nPays        12,000.00 USDC → vendor@cloud.test · bill · sha256 4a1e…0c77\nSigns       you · Platform lead\n✓ Paid      0x81c2…e0aa · Platform team has 108,000 left",
        "json": "{\n  \"version\": 1,\n  \"command\": \"org department pay\",\n  \"environment\": {\n    \"name\": \"devnet\",\n    \"chainId\": 84532\n  },\n  \"outcome\": \"succeeded\",\n  \"data\": {\n    \"payment\": {\n      \"paymentId\": \"0x6c0d…\",\n      \"kind\": 0,\n      \"amount\": \"12000.00\",\n      \"token\": \"USDC\",\n      \"recipient\": \"vendor@cloud.test\",\n      \"documentHash\": \"0x4a1e…0c77\"\n    },\n    \"department\": {\n      \"key\": \"platform\",\n      \"left\": \"108000.00\"\n    }\n  }\n}",
        "sdk": "await org.departments.pay(\"platform\", { to: \"vendor@cloud.test\", amount: \"12000\", document: { file: \"./invoice-0042.pdf\" } });",
        "returns": "{\n  \"ok\": true,\n  \"value\": {\n    \"payment\": {\n      \"kind\": \"bill\",\n      \"amount\": \"12000.00\"\n    },\n    \"department\": {\n      \"left\": \"108000.00\"\n    }\n  }\n}"
      },
      "refusals": [
        {
          "code": "PAYROLL_BUDGET_EXCEEDED",
          "exit": 2,
          "when": "More than the budget has left this period",
          "contract": "`OverBudget(id, left, requested)`"
        },
        {
          "code": "WRONG_STATE",
          "exit": 2,
          "when": "The budget or one above it is closed",
          "contract": "`BudgetIsClosed(id)`"
        },
        {
          "code": "PAYROLL_BUDGET_EXCEEDED",
          "exit": 2,
          "when": "Within the budget but over the Roles payout ceiling (the backstop)",
          "contract": "Roles `AllowanceExceeded`"
        },
        {
          "code": "ROLE_PERMISSION_DENIED",
          "exit": 4,
          "when": "The caller is not this budget's office holder or above",
          "contract": "`NotAuthorised` / `NotOfficeHolder` / `OnlyBoard`"
        }
      ],
      "call": "`Budgets.spend(id, recipient, amount, kind, documentHash, jobNonce)`, which pays through Roles into `Payments.send`.",
      "concepts": [
        "c-budgets",
        "c-payments"
      ]
    },
    "source": "apps/docs/factory/operations/org.department.pay.yaml"
  },
