  "org.invite.cancel": {
    "id": "org.invite.cancel",
    "area": "governance",
    "command": "org invite cancel",
    "title": "Cancel an invitation",
    "sdk": "client.org(orgId).invitations.cancel",
    "row": null,
    "about": "Cancels an invitation the Organization sent that has not been accepted. Any rights the offer had set up on the chain are then cleaned up. Use it when you invited the wrong person or offered the wrong grants.",
    "who": "A member who can manage people in the Organization. On Protocol v4 that is the wearer of the company's People hat; before v4, a member with the Manage people permission.",
    "changes": "It ends the invitation as cancelled and starts removing anything its offer set up.",
    "notes": [
      "Cancelling an invitation that is already cancelled returns it as it is.",
      "An invitation with no grants ends at once, with nothing to clean up.",
      "A script must pass `--confirm`."
    ],
    "mistakes": [
      {
        "what": "The invitation was already accepted",
        "fix": "It refuses with `WRONG_STATE`. Remove the member's rights with `org allowance revoke` instead."
      },
      {
        "what": "The Director proposal that sets up its grants may still run",
        "fix": "It refuses with `WRONG_STATE`. Reject that proposal with `capxul org proposal reject`, then cancel."
      }
    ],
    "returns": [
      {
        "field": "id",
        "meaning": "The invitation."
      },
      {
        "field": "phase",
        "meaning": "`cancelled` at once for a Seat-only offer; `revoking` while an offer with grants is cleaned up, then `cancelled`."
      },
      {
        "field": "endingReason",
        "meaning": "`cancelled`."
      },
      {
        "field": "recovery",
        "meaning": "`cleanup_pending` while the chain cleanup runs, or `null` once nothing is pending."
      },
      {
        "field": "offers",
        "meaning": "What it offered, kept for the record."
      },
      {
        "field": "delivery",
        "meaning": "What the invitation email had done."
      }
    ],
    "refusals": [
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "You cannot manage people in this Organization, or the invitation is not one it sent."
      },
      {
        "code": "WRONG_STATE",
        "when": "The offer was already accepted, it ended for another reason, or the Director proposal that sets up its grants may still run and must be rejected first."
      },
      {
        "code": "NOT_AUTHENTICATED",
        "when": "No valid sign-in on this machine."
      }
    ],
    "acceptance": [
      {
        "claim": "An unsigned authorizing offer is retired without chain cleanup, and releases its triple and configure command.",
        "was": [
          "backend cancel.test.ts"
        ]
      },
      {
        "claim": "A signed configuration is refused before reconciliation.",
        "was": [
          "backend cancel.test.ts"
        ]
      },
      {
        "claim": "A verified pending offer starts cleanup.",
        "was": [
          "backend cancel.test.ts"
        ]
      },
      {
        "claim": "A non-Admin is refused.",
        "was": [
          "backend cancel.test.ts"
        ]
      },
      {
        "claim": "It schedules one event for the Admin, and reports nothing on a replay.",
        "was": [
          "backend cancel.test.ts"
        ]
      }
    ],
    "events": [],
    "designed": null,
    "source": "apps/docs/factory/operations/org.invite.cancel.yaml"
  },
