        "sdk": "await org.members.grant(\"sam@acme.test\", { permission: \"issue-invoices\" });",
        "returns": "{\n  \"ok\": true,\n  \"value\": {\n    \"status\": \"awaiting_approvals\",\n    \"permission\": \"issue-invoices\",\n    \"hat\": \"0x0000…0102\"\n  }\n}"
