  "org.member.revoke": {
    "id": "org.member.revoke",
    "area": "governance",
    "command": "org member revoke",
    "title": "Revoke a permission",
    "sdk": "client.org(orgId).members.revoke",
    "row": null,
    "about": "Proposes taking a permission, Manage books, issue invoices or (on v4) Manage people, back from a member, then opens your approval in the browser. The member stays a member. The change applies once the proposal executes.",
    "who": "A Director of the Organization.",
    "changes": "It opens a proposal at the Safe's next nonce and changes nothing until enough Directors approve.",
    "notes": [
      "`--no-wait` returns once your approval is open."
    ],
    "mistakes": [
      {
        "what": "The member does not hold that permission",
        "fix": "It refuses with `WRONG_STATE`. Check with `capxul org member list`."
      },
      {
        "what": "A change to the same member's permission is already waiting",
        "fix": "It refuses with `WRONG_STATE`. Approve or reject that proposal first."
      }
    ],
    "returns": [
      {
        "field": "change.changeId",
        "meaning": "The change, carried by the proposal."
      },
      {
        "field": "change.change",
        "meaning": "`revoke`."
      },
      {
        "field": "change.permission",
        "meaning": "`manage-books`, `issue-invoices` or `manage-people`."
      },
      {
        "field": "change.email",
        "meaning": "The member it names."
      },
      {
        "field": "change.name",
        "meaning": "Their name, or `null`."
      },
      {
        "field": "change.state",
        "meaning": "`proposed` until the proposal executes, then `applied`; `ended` if it is rejected or replaced."
      },
      {
        "field": "proposal.proposalId",
        "meaning": "The proposal, to follow with `capxul org proposal wait`."
      },
      {
        "field": "proposal.nonce",
        "meaning": "The Safe nonce it took."
      },
      {
        "field": "proposal.status",
        "meaning": "`awaiting_approvals` until enough Directors approve, then `executed`."
      },
      {
        "field": "proposal.threshold",
        "meaning": "How many Directors must approve."
      },
      {
        "field": "proposal.approvals",
        "meaning": "Which Directors have approved so far."
      },
      {
        "field": "proposal.note",
        "meaning": "Your `--note`, or the change in words."
      }
    ],
    "refusals": [
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "Your personal Safe is not one of the Organization Safe's owners. Nothing was signed."
      },
      {
        "code": "INVALID_INPUT",
        "when": "The email is not a current member of the Organization."
      },
      {
        "code": "WRONG_STATE",
        "when": "The member does not hold that permission (on a v4 company, their personal Safe does not wear its officer hat), or a change to the same member's permission is still waiting for the Directors."
      },
      {
        "code": "WRONG_STATE",
        "when": "On a v4 company, the member has no claimed personal Safe."
      },
      {
        "code": "FEATURE_NOT_AVAILABLE",
        "when": "Manage people on an Organization set up before v4, where it is a Roles Permission."
      },
      {
        "code": "NOT_AUTHENTICATED",
        "when": "No valid sign-in on this machine."
      }
    ],
    "acceptance": [
      {
        "claim": "A revoke is a Director proposal, applied once it executes, and names the change or keeps the Director's note.",
        "was": [
          "backend revoke.test.ts"
        ]
      },
      {
        "claim": "A caller who is not a Director, an email that is not a current Seat, and a revoke of what the Seat does not hold are each refused.",
        "was": [
          "backend revoke.test.ts"
        ]
      },
      {
        "claim": "A second change is refused while one waits, and a caller who is not signed in is refused.",
        "was": [
          "backend revoke.test.ts"
        ]
      },
      {
        "claim": "It schedules one event for the proposing Director, carrying neither the Seat nor the note.",
        "was": [
          "backend revoke.test.ts"
        ]
      },
      {
        "claim": "On a v4 company the proposal rules the Seat's Safe out of the officer hat, in good standing, and a Seat whose Safe does not wear the hat is refused.",
        "was": [
          "backend revoke.test.ts"
        ]
      }
    ],
    "events": [],
    "designed": {
      "slice": "W2",
      "summary": "Take a permission back by ruling the member out of its officer hat. The member stays a member, and Capxul stops honouring the permission as soon as Hats says they no longer wear it.",
      "synopsis": "capxul org member revoke <email> --permission manage-books|issue-invoices|manage-people [--note <text>] [--no-wait]",
      "who": "The Board.",
      "signs": "Board: a Safe proposal the Directors approve, `capxul org proposal approve`.",
      "method": "client.org(orgId).members.revoke",
      "flags": [
        {
          "flag": "`--permission`",
          "meaning": "The Books, Invoicing or People hat"
        }
      ],
      "example": {
        "cli": "$ capxul org member revoke sam@acme.test --permission issue-invoices\nHat         Invoicing · worn by mia@acme.test, sam@acme.test\nRemoves     sam@acme.test\nSigns       Board · 1 of 2\n✓ Approved  1 of 2 · other director: capxul org proposal approve sp_01KA…",
        "sdk": "await org.members.revoke(\"sam@acme.test\", { permission: \"issue-invoices\" });",
        "returns": "{\n  \"ok\": true,\n  \"value\": {\n    \"status\": \"awaiting_approvals\",\n    \"permission\": \"issue-invoices\"\n  }\n}"
      },
      "refusals": [
        {
          "code": "WRONG_STATE",
          "exit": 2,
          "when": "The member does not wear the hat",
          "contract": "none"
        },
        {
          "code": "ROLE_PERMISSION_DENIED",
          "exit": 4,
          "when": "The caller is not a Director",
          "contract": "Signer Gate `InsufficientValidSignatures`"
        }
      ],
      "call": "One Board batch: `Hats.setHatWearerStatus(hat, memberSafe, false, true)`, which burns the member's hat. The company Safe is the hat's eligibility. The member stays in good standing: Hats refuses to mint a hat to a wearer in bad standing, so `false, false` would block every later grant.",
      "concepts": [
        "c-board"
      ]
    },
    "source": "apps/docs/factory/operations/org.member.revoke.yaml"
  },
