  "org.proposal.approve": {
    "id": "org.proposal.approve",
    "area": "governance",
    "command": "org proposal approve",
    "title": "Approve a proposal",
    "sdk": "client.org(orgId).proposals.approve",
    "row": "organizations.proposals.requestApproval",
    "about": "Opens your approval of a proposal in the browser and follows it until it lands on the chain. The approval that reaches the threshold executes the proposal instead. Afterwards the command says whether it executed or how many more Directors must approve.",
    "who": "A Director of the Organization.",
    "changes": "You sign your approval of the proposal on the approval page, and Capxul sends it from your personal Safe.",
    "notes": [
      "Asking again for the same proposal opens the same approval.",
      "Proposals execute in nonce order. One at a later nonce collects approvals but executes only after the ones before it.",
      "An AI member with its own key signs here without the browser.",
      "`--no-wait` returns once your approval is open. By default the command follows it until the approval lapses."
    ],
    "mistakes": [
      {
        "what": "You already approved and the threshold is not reached yet",
        "fix": "It refuses with `WRONG_STATE`. Wait for the other Directors."
      },
      {
        "what": "The proposal already executed, or was rejected or replaced",
        "fix": "It refuses with `WRONG_STATE`. Nothing moves."
      },
      {
        "what": "The proposal changed on the chain before your signed approval was sent",
        "fix": "It fails with `WRONG_STATE` and nothing moves. Run `org proposal approve` again."
      },
      {
        "what": "The proposal carries a call the chain refuses, such as one the v4 Signer Gate does not allow",
        "fix": "The approval that would execute it refuses with `WRONG_STATE` (`execution_reverts`) before you sign. Reject it with `org proposal reject`."
      }
    ],
    "returns": [
      {
        "field": "approvalId",
        "meaning": "Your approval, the page the CLI opens."
      },
      {
        "field": "url",
        "meaning": "The approval page."
      },
      {
        "field": "kind",
        "meaning": "`safe_proposal`."
      },
      {
        "field": "state",
        "meaning": "`pending` until you sign, `approved` once signed, `consumed` once Capxul has sent it; `rejected` or `expired` end it unsigned."
      },
      {
        "field": "actor",
        "meaning": "The Organization whose Safe it signs for."
      },
      {
        "field": "summary",
        "meaning": "What the page shows before you sign: title, from, to, amount, recipients and network."
      },
      {
        "field": "operation",
        "meaning": "The exact user operation the signature covers; `operation.digest` is the one thing the key signs."
      },
      {
        "field": "signer.address",
        "meaning": "The key that must sign, the owner key of your personal Safe."
      },
      {
        "field": "expiresAt",
        "meaning": "When the approval lapses with its sponsorship."
      },
      {
        "field": "createdAt",
        "meaning": "When it was opened."
      },
      {
        "field": "reviewedAt",
        "meaning": "When you first opened the page; null until then."
      },
      {
        "field": "decidedAt",
        "meaning": "When you approved or rejected it; null until then."
      },
      {
        "field": "consumedAt",
        "meaning": "When Capxul sent it; null until then."
      }
    ],
    "refusals": [
      {
        "code": "CAPABILITY_UNAVAILABLE",
        "when": "From the SDK, the client has no signer to sign with. The CLI opens the approval page instead."
      },
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "You are not a Director of the Organization, or on a v4 company your Director hat lapsed (reason `director_hat_lapsed`). Nothing was signed."
      },
      {
        "code": "INVALID_INPUT",
        "when": "No proposal with that ID belongs to this Organization."
      },
      {
        "code": "WRONG_STATE",
        "when": "The proposal already executed, was rejected or replaced; you already approved it and the threshold is not reached yet; the proposal changed on the chain before your signed approval was sent; or the chain refuses the execution your approval would send (`currentState` `execution_reverts`; on a v4 company the Signer Gate refuses the payload). Nothing was signed."
      },
      {
        "code": "NOT_AUTHENTICATED",
        "when": "No valid sign-in on this machine."
      }
    ],
    "acceptance": [
      {
        "claim": "A 2-of-2 Safe pays only when the second Director's approval executes it; on a 1-of-1 Safe the proposer's own approval executes.",
        "was": [
          "backend request-approval.test.ts"
        ]
      },
      {
        "claim": "An approval is done only once the chain holds it, and one the chain never shows fails as dropped when its window ends.",
        "was": [
          "backend request-approval.test.ts"
        ]
      },
      {
        "claim": "Asking twice answers with the same approval.",
        "was": [
          "backend request-approval.test.ts"
        ]
      },
      {
        "claim": "A participant who is not a Director cannot open an approval, and a signature from another key is refused with nothing sent.",
        "was": [
          "backend request-approval.test.ts"
        ]
      },
      {
        "claim": "With the owner-safe-proposals gate off, no approval opens, and a gate turned off later stops the send.",
        "was": [
          "backend request-approval.test.ts"
        ]
      },
      {
        "claim": "It says which approval of the threshold the caller signs and when it executes.",
        "was": [
          "cli presentation.test.ts"
        ]
      },
      {
        "claim": "An execution the chain refuses is refused `WRONG_STATE` before the Director signs, and nothing is sent.",
        "was": [
          "backend request-approval.test.ts"
        ]
      }
    ],
    "events": [],
    "designed": {
      "slice": "W2",
      "summary": "Same command on v4. A Board proposal is one company Safe transaction. Each Director approves its hash from their own personal Safe, gaslessly, with `approveHash`. The approval that reaches the threshold also executes it, and the Signer Gate counts only Directors who still wear the Director hat.",
      "synopsis": "capxul org proposal approve <proposal> [--no-wait] [--timeout-seconds <n>] · get · list · wait",
      "who": "A Director of the Organization.",
      "signs": "You: your own Safe, sponsored by Capxul's paymaster. The last approval also sends `execTransaction`.",
      "method": "client.org(orgId).proposals.approve",
      "flags": [],
      "example": {
        "cli": "$ capxul org proposal approve sp_01K5…\nProposal    Office costs allowance · nonce 4 · Board 2 of 2\nSigns       you · Director · approval 2 of 2 executes it\n✓ Executed  0x5d2a…e801",
        "sdk": "await org.proposals.approve(\"sp_01K5…\");",
        "returns": "{\n  \"ok\": true,\n  \"value\": {\n    \"status\": \"executed\",\n    \"approvals\": 2,\n    \"threshold\": 2\n  }\n}"
      },
      "refusals": [
        {
          "code": "WRONG_STATE",
          "exit": 2,
          "when": "An earlier nonce is still waiting, or the proposal already executed or was rejected",
          "contract": "Safe `GS025` (nonce moved on)"
        },
        {
          "code": "ROLE_PERMISSION_DENIED",
          "exit": 4,
          "when": "You do not wear the Director hat, or your hat lapsed",
          "contract": "Signer Gate `InsufficientValidSignatures`"
        }
      ],
      "call": "`Safe.approveHash(safeTxHash)` from your Safe. At the threshold, Capxul first calls `HatsSignerGate.removeSigner` for every owner whose hat lapsed, then `Safe.execTransaction(…)` with each approval as a `v = 1` signature, which the Gate checks.",
      "also": [
        "org proposal get",
        "org proposal list",
        "org proposal wait"
      ],
      "concepts": [
        "c-board"
      ]
    },
    "source": "apps/docs/factory/operations/org.proposal.approve.yaml"
  },
