        "returns": "{\n  \"ok\": true,\n  \"value\": {\n    \"roundId\": \"rd_01K8…\",\n    \"adjusted\": [\n      {\n        \"class\": \"Series A\",\n        \"before\": \"2.5103\",\n        \"after\": \"2.4745\"\n      },\n      {\n        \"class\": \"Series B\",\n        \"before\": \"5.9311\",\n        \"after\": \"5.0079\"\n      }\n    ]\n  }\n}"
