  "org.show": {
    "id": "org.show",
    "area": "organizations",
    "command": "org show",
    "title": "Show an Organization",
    "sdk": "client.org(orgId).setup.get",
    "row": null,
    "about": "Reads where the Organization's setup stands. Once setup is ready, it also shows the Safe's address, its Directors, how many approvals each change needs, the next nonce and how many proposals wait. Use it to check on an Organization before you act in it.",
    "who": "A member of the Organization, or the founder while setup is still unfinished.",
    "changes": "Nothing: it only reads.",
    "notes": [
      "Without `--org` it uses the Organization you chose with `capxul use org`. If you have no choice saved and exactly one unfinished setup, it shows that one.",
      "A setup that is not ready prints the exact command to resume it or read it again."
    ],
    "mistakes": [
      {
        "what": "You have several unfinished setups and gave no `--org` from a script",
        "fix": "It refuses with `CLI_USAGE`. Pass `--org` with the ID from `capxul org list`."
      },
      {
        "what": "You named an Organization this session cannot reach",
        "fix": "It refuses with `ROLE_PERMISSION_DENIED`. Sign in as a member, or ask to be added."
      }
    ],
    "returns": [
      {
        "field": "setup",
        "meaning": "Where setup stands, such as `ready`."
      },
      {
        "field": "steps",
        "meaning": "The setup steps already finished, in order: `safe_minted`, `money_deployed` and `installed`."
      },
      {
        "field": "board",
        "meaning": "Once ready, `{ directors, threshold }`, the number of Directors and how many must approve a change; `null` before."
      }
    ],
    "refusals": [
      {
        "code": "CLI_USAGE",
        "when": "Several unfinished setups and no `--org` in a script."
      },
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "This session cannot reach the Organization."
      },
      {
        "code": "NOT_AUTHENTICATED",
        "when": "No valid sign-in on this machine."
      }
    ],
    "acceptance": [
      {
        "claim": "A read never advances setup.",
        "was": [
          "backend get.test.ts"
        ]
      },
      {
        "claim": "The founder reads their own setup, and another founder's reads as absent.",
        "was": [
          "backend get.test.ts"
        ]
      },
      {
        "claim": "While an authority hold is in place, only a receipt-backed active member reads setup.",
        "was": [
          "backend get.test.ts"
        ]
      },
      {
        "claim": "A ready setup whose proof is final offers no recovery.",
        "was": [
          "backend get.test.ts"
        ]
      },
      {
        "claim": "When the setup read fails, it names the saved Organization and the exact retry command.",
        "was": [
          "cli org.test.ts"
        ]
      },
      {
        "claim": "It never copies an SDK-provided recovery action, and offers no writes for an access refusal.",
        "was": [
          "cli recovery-output.test.ts"
        ]
      }
    ],
    "events": [],
    "designed": {
      "slice": "W2",
      "summary": "Same command on v4. Setup steps are the Safe mint, the Installer deploy and the install batch. A ready Organization shows its Directors and threshold from the Signer Gate, its top budgets and its waiting Board proposals.",
      "synopsis": "capxul org show [--org <org>] · capxul org wait [--org <org>] [--timeout-seconds <n>]",
      "who": "A member of the Organization, or the founder while setup is unfinished.",
      "signs": "Nothing: it only reads",
      "method": "client.org(orgId).setup.get",
      "flags": [],
      "example": {
        "cli": "$ capxul org show --org acme\nAcme Ltd    ready · Safe 0x4c1d…7e02 · Signer Gate 0x88e0…19bb\nBoard       1 Director · signs 1 of 1 · next nonce 3 · 0 proposals waiting\nBudgets     Acme · USDC · 600,000 a year · 412,000 left",
        "sdk": "const setup = await client.org(\"acme\").setup.get();",
        "returns": "{\n  \"ok\": true,\n  \"value\": {\n    \"setup\": \"ready\",\n    \"steps\": [\n      \"safe_minted\",\n      \"money_deployed\",\n      \"installed\"\n    ],\n    \"board\": {\n      \"directors\": 1,\n      \"threshold\": 1\n    }\n  }\n}"
      },
      "refusals": [
        {
          "code": "ROLE_PERMISSION_DENIED",
          "exit": 4,
          "when": "You are not a member of this Organization",
          "contract": "none"
        }
      ],
      "call": "Reads only: the minter's and the Installer's events (`MoneyDeployed`), the Safe's modules and guard, `HatsSignerGate.isValidSigner` for each owner, the Safe's threshold and nonce, and `Budgets.budgetOf` for each top budget.",
      "also": [
        "org wait"
      ],
      "concepts": [
        "l-company",
        "c-board"
      ]
    },
    "source": "apps/docs/factory/operations/org.show.yaml"
  },
