  "payment.cancel": {
    "id": "payment.cancel",
    "area": "payments",
    "command": "payment cancel",
    "title": "Cancel a scheduled payment",
    "sdk": "client.approvals.prepare",
    "row": "payments.lifecycles.prepareScoped",
    "about": "Cancels a scheduled payment that you signed, before its date. The CLI prepares a void on the payment's own nonce lane and gives you an approval link. You approve the void in your browser, and the CLI follows it until the payment reads `cancelled`.",
    "who": "The person who scheduled the payment. With `--org`, someone who can act for that Organization's payment. With `--org --as-directors`, a Director.",
    "changes": "You sign the void on the approval page. Once the void lands, the payment can never be sent. With `--as-directors`, it opens a proposal that the Directors approve at the threshold.",
    "notes": [
      "With `--json` it returns the approval link and a `capxul payment wait` command at once. Otherwise it follows the approval until it lapses, or for `--timeout-seconds`.",
      "An AI that signs with its own key signs the void at once.",
      "The approval ends when the void is sent. The payment can read `scheduled` for a short time after that. The CLI reads it for up to three minutes.",
      "On Protocol v4 the Directors cancel a payment they dated (`--as-directors`) with one Board proposal at the Safe's next nonce: one `Budgets.cancel` per item from the company Safe. When it executes, the budget's reservation is freed and the payment reads `cancelled` (CAP-1238)."
    ],
    "mistakes": [
      {
        "what": "The payment does not read `cancelled` after the void",
        "fix": "It fails with `WRONG_STATE` and names `capxul payment get`. Read the payment to see what it became."
      },
      {
        "what": "You let the approval expire, or rejected it on the approval page",
        "fix": "Expiry ends with `WRONG_STATE` and a rejection with `CANCELLED`. The payment stays scheduled in both cases."
      }
    ],
    "returns": [
      {
        "field": "status",
        "meaning": "With `--json`, `awaiting_approval` while the approval waits for you."
      },
      {
        "field": "approvalId",
        "meaning": "The approval's ID, which `capxul payment wait` follows."
      },
      {
        "field": "approvalUrl",
        "meaning": "The approval page where you sign."
      },
      {
        "field": "paymentIds",
        "meaning": "The payments the approval covers."
      },
      {
        "field": "expiresAt",
        "meaning": "When the approval lapses."
      },
      {
        "field": "next",
        "meaning": "The `capxul payment wait` command that follows it."
      },
      {
        "field": "approval",
        "meaning": "When followed to the end, the approval as it ended."
      },
      {
        "field": "payments",
        "meaning": "When followed to the end, each payment it moved, as it stands."
      }
    ],
    "refusals": [
      {
        "code": "CLI_USAGE",
        "when": "The payment ID is malformed."
      },
      {
        "code": "WRONG_STATE",
        "when": "The payment is no longer held, is already cancelled, the approval expired, or after the void it does not read `cancelled`."
      },
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "You cannot act for that payment, or for an Organization-funded commitment you are not a Director."
      },
      {
        "code": "NOT_AUTHENTICATED",
        "when": "You are not signed in."
      }
    ],
    "acceptance": [
      {
        "claim": "A cancel of a payment that is no longer held, or already cancelled, is refused before anything is built.",
        "was": [
          "backend prepare-scoped.test.ts"
        ]
      },
      {
        "claim": "On Protocol v4 the Board cancels only a waiting schedule it stored for its own Organization, and once its proposal executes the schedule, its command and its Payment are cancelled, once.",
        "was": [
          "backend payments/schedules/tests/board-cancel.test.ts"
        ]
      },
      {
        "claim": "A held payment stays held when its cancel fails before it is signed.",
        "was": [
          "backend prepare-scoped.test.ts"
        ]
      },
      {
        "claim": "Only a Director can cancel an Organization-funded commitment, and each Director prepares their own.",
        "was": [
          "backend prepare-scoped.test.ts"
        ]
      },
      {
        "claim": "It prepares the void for the approval page and hands an agent the link.",
        "was": [
          "cli cancel.test.ts"
        ]
      },
      {
        "claim": "It cancels an Organization's scheduled payment in that Organization, and refuses a malformed ID before any session.",
        "was": [
          "cli cancel.test.ts"
        ]
      }
    ],
    "events": [],
    "designed": {
      "slice": "W2",
      "summary": "Same command on v4, for three kinds of waiting payment. A personal dated payment is voided on its nonce lane, as today. A budget's dated payment is cancelled in Budgets, which frees its reservation, any time until it is paid. A payment into a claim escrow is refunded until the payee collects it.",
      "synopsis": "capxul payment cancel <payment> [--org <org> [--as-directors]] [--timeout-seconds <n>]",
      "who": "The payer. For a budget's dated payment, the wearer of the budget's hat or above. For a claim escrow the company Safe owns, the Board.",
      "signs": "Personal: your own Safe. A budget's dated payment: your own Safe calls Budgets. A company-owned escrow: Board: a Safe proposal the Directors approve, `capxul org proposal approve`.",
      "method": "client.payments.cancel",
      "flags": [
        {
          "flag": "`--as-directors`",
          "meaning": "For a dated payment the Board scheduled, or a claim escrow the company Safe owns"
        }
      ],
      "example": {
        "cli": "$ capxul payment cancel pay_01K2… --org acme\nPayment     4,000.00 USDC → supplier@parts.test · due 1 Dec 2026\nFrees       4,000 in Operations this year\nSigns       you · Ops lead\n✓ Cancelled sched 17 · Operations has 46,000 left",
        "sdk": "await client.payments.cancel(\"pay_01K2…\", { org: \"acme\" });",
        "returns": "{\n  \"ok\": true,\n  \"value\": {\n    \"payment\": {\n      \"status\": \"cancelled\"\n    },\n    \"budget\": {\n      \"left\": \"46000.00\"\n    }\n  }\n}"
      },
      "refusals": [
        {
          "code": "WRONG_STATE",
          "exit": 2,
          "when": "The payment already paid, was already cancelled, or the payee already collected the escrow",
          "contract": "`NotPending(id)`; Escrow `JobNotOpen()`"
        },
        {
          "code": "ROLE_PERMISSION_DENIED",
          "exit": 4,
          "when": "You wear no hat on the payment's budget or above it, or you are not the escrow's owner",
          "contract": "`NotAuthorised(id, who)`; Escrow `NotOwner()`"
        }
      ],
      "call": "A budget's dated payment: `Budgets.cancel(scheduledId)`. A claim escrow: `Escrow.refund()` from its owner Safe. A personal dated payment: a void operation on the same nonce, as today.",
      "concepts": [
        "c-payments",
        "c-budgets",
        "c-escrow"
      ]
    },
    "source": "apps/docs/factory/operations/payment.cancel.yaml"
  },
