  "request.cancel": {
    "id": "request.cancel",
    "area": "payments",
    "command": "request cancel",
    "title": "Cancel a request",
    "sdk": "client.account.requests.cancel",
    "row": null,
    "about": "Cancels a request you issued, so it can no longer be paid. Use it when a request was wrong or is no longer owed. A request that is already being paid, paid, declined or cancelled cannot be cancelled.",
    "who": "The person who issued the request. With `--org`, a member who holds issue invoices in that Organization.",
    "changes": "It marks the request cancelled. It moves no money.",
    "notes": [
      "A draft, sent or viewed request can be cancelled, even after it has expired.",
      "From a script, pass `--confirm`. A terminal shows the request and always asks first.",
      "If the reply is lost, read the request with `request get` before another write."
    ],
    "mistakes": [
      {
        "what": "The request is already being paid, paid, declined or cancelled",
        "fix": "It is refused with `WRONG_STATE`."
      },
      {
        "what": "You ran it from a script without `--confirm`",
        "fix": "It is refused with `CLI_USAGE`. Pass `--confirm`."
      }
    ],
    "returns": [
      {
        "field": "id",
        "meaning": "The request's ID."
      },
      {
        "field": "status",
        "meaning": "`cancelled`."
      },
      {
        "field": "amount",
        "meaning": "Its amount."
      },
      {
        "field": "reference",
        "meaning": "What it was for."
      }
    ],
    "refusals": [
      {
        "code": "CLI_USAGE",
        "when": "From a script without `--confirm`, or the request is not found or not yours."
      },
      {
        "code": "WRONG_STATE",
        "when": "The request is already being paid, paid, declined or cancelled."
      },
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "With `--org`, you do not hold issue invoices."
      },
      {
        "code": "NOT_AUTHENTICATED",
        "when": "You are not signed in."
      }
    ],
    "acceptance": [
      {
        "claim": "Each guarded decision reports its own transition from the committed row.",
        "was": [
          "backend cancel.test.ts"
        ]
      },
      {
        "claim": "At a terminal it previews the exact issued request and asks before it cancels.",
        "was": [
          "cli read.test.ts"
        ]
      }
    ],
    "events": [],
    "designed": {
      "slice": "W2",
      "summary": "Same command on v4, and still nothing on chain. Cancelling stops a payer from being asked, but an invoice escrow that already holds the amount still pays you through v4 `Payments.send`.",
      "synopsis": "capxul request cancel <id> [--org <org>] [--confirm]",
      "who": "The person who issued the request. With `--org`, a wearer of the Organization's Invoicing hat.",
      "signs": "Nothing: you sign nothing to cancel.",
      "method": "client.account.requests.cancel",
      "flags": [],
      "example": {
        "cli": "$ capxul request cancel req_01K3… --org parts --confirm\nRequest     1,200.00 USDC from client@shop.test · INV-0042\n✓ Cancelled req_01K3…",
        "sdk": "await client.account.requests.cancel(\"req_01K3…\");",
        "returns": "{\n  \"ok\": true,\n  \"value\": {\n    \"request\": {\n      \"requestId\": \"req_01K3…\",\n      \"status\": \"cancelled\"\n    }\n  }\n}"
      },
      "refusals": [
        {
          "code": "WRONG_STATE",
          "exit": 2,
          "when": "The request is already being paid, paid, declined or cancelled",
          "contract": "none on chain; the request's status decides"
        }
      ],
      "call": "None. `request cancel` writes nothing on chain. An escrow already holding the amount still pays out: anyone calls `EscrowFactory.deploy(terms, salt)` and `Escrow.payout()`, which pays through `Payments.send`, and the request reads paid. An escrow that holds less is closed.",
      "also": [
        "request issue"
      ],
      "concepts": [
        "c-escrow",
        "c-payments"
      ]
    },
    "source": "apps/docs/factory/operations/request.cancel.yaml"
  },
