  "request.issue": {
    "id": "request.issue",
    "area": "payments",
    "command": "request issue",
    "title": "Request a payment",
    "sdk": "client.account.requests.issue",
    "row": null,
    "about": "Asks someone to pay you: their email, an amount and a reference that tells them what it is for. It returns the request with a checkout link when one applies. With `--org`, the Organization issues the request.",
    "who": "A signed-in person. With `--org`, a member who holds issue invoices in that Organization.",
    "changes": "It creates a payment request that the payer sees in their inbox. Nothing is paid until they pay it.",
    "notes": [
      "The asset defaults to USDC and must be one your account, or the Organization, holds.",
      "From a script, give the email, the amount and `--reference`, and pass `--confirm`. A terminal asks for what is missing and always asks before it issues.",
      "The reference can be up to 120 characters. `--input` takes the same request as JSON, with an optional `expiresAt` that must be in the future.",
      "If the reply is lost, check `request list` before you issue again. The request may already exist.",
      "On Protocol v4 a request to an email not on Capxul, an Invoice or a basic request, is paid into an invoice escrow at the v4 `EscrowFactory.predictAddress(terms, salt)`; `Pay to` names it. Nothing is written on chain when you issue. Once it holds the amount, Capxul deploys it and `Escrow.payout()` pays your Safe through v4 `Payments.send`, and the request reads paid."
    ],
    "mistakes": [
      {
        "what": "You ran it from a script without `--confirm`",
        "fix": "It is refused with `CLI_USAGE`. Pass `--confirm` for each write."
      },
      {
        "what": "You issued for an Organization without issue invoices",
        "fix": "It is refused with `ROLE_PERMISSION_DENIED`. Ask a Director to grant you issue invoices."
      }
    ],
    "returns": [
      {
        "field": "scope",
        "meaning": "Whether you or the Organization issued it."
      },
      {
        "field": "direction",
        "meaning": "The request's direction, issued."
      },
      {
        "field": "item",
        "meaning": "The request with its ID, payer, amount, reference, status, expiry, documents, any escrow and its checkout link."
      }
    ],
    "refusals": [
      {
        "code": "CLI_USAGE",
        "when": "From a script without `--confirm`, or with both `<email> <amount>` and `--input`."
      },
      {
        "code": "INVALID_INPUT",
        "when": "The request is not valid, such as an Invoice to a bare wallet address."
      },
      {
        "code": "ROLE_PERMISSION_DENIED",
        "when": "With `--org`, you do not hold issue invoices."
      },
      {
        "code": "NOT_AUTHENTICATED",
        "when": "You are not signed in."
      }
    ],
    "acceptance": [
      {
        "claim": "An Invoice to an email not on Capxul is paid through an escrow its email Safe owns, at the address the v4 factory predicts.",
        "was": [
          "backend issue.test.ts"
        ]
      },
      {
        "claim": "A basic request to an email not on Capxul is paid through a v4 escrow of kind 1; one with no payer has no escrow.",
        "was": [
          "backend issue.test.ts"
        ]
      },
      {
        "claim": "An Invoice to a bare wallet address is refused.",
        "was": [
          "backend issue.test.ts"
        ]
      },
      {
        "claim": "An uncertain creation reply recovers from the issued list in the same session; a terminal decline issues nothing even with `--confirm`.",
        "was": [
          "cli issue.test.ts"
        ]
      }
    ],
    "events": [],
    "designed": {
      "slice": "W2",
      "summary": "Same command on v4, and still nothing on chain when you issue. A payer on Capxul pays from their inbox. A payer who is not pays through the checkout link into an invoice escrow at an address fixed by the request's terms, and the escrow pays you once it holds the amount.",
      "synopsis": "capxul request issue <email> <amount> [--asset <symbol>] --reference <text> [--org <org>] [--confirm]",
      "who": "A signed-in person. With `--org`, a wearer of the Organization's Invoicing hat.",
      "signs": "Nothing: you sign nothing to issue or to be paid. Anyone, normally Capxul, deploys and pays out a funded escrow.",
      "method": "client.account.requests.issue",
      "flags": [
        {
          "flag": "`--reference`",
          "meaning": "What it is for; it goes in the request's document, whose hash the payment carries"
        }
      ],
      "example": {
        "cli": "$ capxul request issue client@shop.test 1200 --reference \"INV-0042\" --org parts --confirm\nRequest     1,200.00 USDC from client@shop.test · INV-0042\nCheckout    https://capxul.test/pay/req_01K3… · escrow 0x9a3f…1c20\n✓ Issued    req_01K3… · in their inbox, or paid by card or bank at the link",
        "sdk": "await client.account.requests.issue({ email: \"client@shop.test\", amount: \"1200\", reference: \"INV-0042\" });",
        "returns": "{\n  \"ok\": true,\n  \"value\": {\n    \"request\": {\n      \"requestId\": \"req_01K3…\",\n      \"status\": \"open\",\n      \"checkout\": {\n        \"escrow\": \"0x9a3f…1c20\"\n      }\n    }\n  }\n}"
      },
      "refusals": [
        {
          "code": "ROLE_PERMISSION_DENIED",
          "exit": 4,
          "when": "You do not wear the Organization's Invoicing hat",
          "contract": "`Hats.isWearerOfHat(yourSafe, invoicingHat)` is false"
        },
        {
          "code": "TOKEN_NOT_SUPPORTED",
          "exit": 2,
          "when": "The asset is not one Payments can move exactly (a fee or rebasing token)",
          "contract": "`InexactTransfer(token, expected, received)` at payout"
        }
      ],
      "call": "None at issue. Checkout: the invoice escrow's address is `EscrowFactory.predictAddress(terms, salt)`, with the payer's email Safe as owner, your Safe (or the company Safe) as payee, kind 1 and condition invoice-amount-reached. Once it holds the amount, anyone calls `EscrowFactory.deploy(terms, salt)` and `Escrow.payout()`, which pays through `Payments.send`. `request cancel` writes nothing on chain; an escrow already holding the amount still pays out.",
      "also": [
        "request cancel"
      ],
      "concepts": [
        "c-escrow",
        "c-payments"
      ]
    },
    "source": "apps/docs/factory/operations/request.issue.yaml"
  },
